@RestController @RequestMapping("/api/v1/training-plan-addons") @RequiredArgsConstructor public class TrainingPlanAddonController {private final TrainingPlanAddonService service; @GetMapping @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_ADDON_READ.getCode())") public PageResponse<TrainingPlanAddonDTO.SimpleResponse> list(@RequestParam(required=false) UUID trainingPlanId,@RequestParam(required=false) AddonStatus status,Pageable p){return service.list(trainingPlanId,status,p);} @GetMapping("/{id}") @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_ADDON_READ.getCode())") public TrainingPlanAddonDTO.Response get(@PathVariable UUID id){return service.get(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_ADDON_CREATE.getCode())") public TrainingPlanAddonDTO.Response create(@Valid @RequestBody TrainingPlanAddonDTO.CreateRequest r){return service.create(r);} @PutMapping("/{id}") @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_ADDON_UPDATE.getCode())") public TrainingPlanAddonDTO.Response update(@PathVariable UUID id,@Valid @RequestBody TrainingPlanAddonDTO.UpdateRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority(T(com.dat.ai_receptionist_web.enums.Security.PermissionDefinition).TRAINING_PLAN_ADDON_DELETE.getCode())") public void delete(@PathVariable UUID id){service.delete(id);} }
